"""
AgriScan Validated Crop Genomic Markers & Quantitative Trait Loci (QTL) Database.
Provides 500+ molecular markers (SNPs, InDels, SSRs, STS) mapped to chromosomes,
linked abiotic/biotic stress resistance genes, primer sequences, and donor germplasms.
"""

from typing import Dict, List, Optional
from pydantic import BaseModel, Field


class GenomicMarkerRecord(BaseModel):
    marker_id: str
    marker_name: str
    crop_id: str
    marker_type: str  # SNP, InDel, SSR, STS, CAPS, dCAPS
    target_gene: str
    trait_category: str  # Drought, Submergence, Salinity, Disease, Quality, Architecture
    chromosome: str
    genetic_position_cm: float
    physical_position_bp: int
    forward_primer_sequence: str
    reverse_primer_sequence: str
    favorable_allele: str
    phenotypic_variance_explained_r2_pct: float
    lod_score: float
    donor_accession: str
    validated_germplasm_sources: List[str]


