def get_marker(marker_id: str) -> Optional[GenomicMarkerRecord]:
    return GENOMIC_MARKER_REGISTRY.get(marker_id)

def list_all_markers() -> List[GenomicMarkerRecord]:
    return list(GENOMIC_MARKER_REGISTRY.values())
